request.user_message:
Abstract the following semantic predicate cluster into exactly one reusable predicate.

Cluster ID:
ternary-001

Cluster Arity:
3

Cluster Members:
[
  {
    "name": "CHECKS_PREREQUISITE_AVAILABILITY",
    "definition": "The reasoning identifies a tool, resource, or environment capability on which a planned or contemplated action depends, a check action queries that prerequisite's availability, version, or readiness, and the observation reports its status.",
    "parameters": [
      {
        "name": "prerequisite_reasoning",
        "type": "reasoning",
        "description": "The reasoning node indicating that a planned or contemplated action depends on a required capability or resource, or that its availability must be verified."
      },
      {
        "name": "check_action",
        "type": "action",
        "description": "The action that queries availability, version, or readiness of the prerequisite."
      },
      {
        "name": "check_result",
        "type": "observation",
        "description": "The observation reporting the prerequisite's availability, version, or readiness."
      }
    ],
    "assertion_conditions": [
      "The reasoning links a planned or contemplated action to a prerequisite tool, resource, capability, or environment condition.",
      "The check action queries the availability, version, or readiness of that prerequisite rather than performing the planned work itself.",
      "The observation reports whether the prerequisite is available or ready."
    ],
    "exclusion_conditions": [
      "No planned or contemplated action depends on the checked prerequisite.",
      "The check action queries something unrelated to the stated dependency.",
      "The observation does not report availability, version, or readiness of the prerequisite."
    ]
  },
  {
    "name": "REMEDIES_MISSING_CAPABILITY",
    "definition": "The reasoning identifies a specific prerequisite that the task requires but that is absent, stale, or otherwise insufficient — such as a missing tool, library, package, credential, or an unprepared configuration or package index; a provisioning action installs, fetches, refreshes, or otherwise supplies that prerequisite; and an observation confirms that the prerequisite has become available.",
    "parameters": [
      {
        "name": "gap_reasoning",
        "type": "reasoning",
        "description": "The reasoning node identifying the prerequisite that is missing, stale, or otherwise insufficient and required for the task."
      },
      {
        "name": "provisioning_action",
        "type": "action",
        "description": "The action that installs, fetches, refreshes, or otherwise provisions the identified prerequisite."
      },
      {
        "name": "confirmation_observation",
        "type": "observation",
        "description": "The observation reporting that the prerequisite has been installed, prepared, or is now available."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a specific prerequisite — a dependency, tool, library, package, credential, or an insufficient configuration or index state — as missing or inadequate and required for the task.",
      "The provisioning action is directed at supplying, installing, or refreshing that identified prerequisite rather than at performing the task's primary work itself.",
      "The observation reports successful installation, successful preparation, or confirmed availability of the prerequisite."
    ],
    "exclusion_conditions": [
      "No specific missing or inadequate prerequisite is identified.",
      "The action does not provision the identified prerequisite, or merely retries the previously failing operation without supplying anything.",
      "The observation does not confirm availability, or the provisioning outcome is left unknown.",
      "The action provisions something merely convenient rather than a prerequisite identified as required for the task."
    ]
  },
  {
    "name": "SURVEYS_ENVIRONMENT_STATE_FOR_PLANNING",
    "definition": "The reasoning indicates that some environment or resource state is unknown, unchecked, or relevant to planning; a reconnaissance action inspects, lists, or queries that state; and the resulting observation reports state information that can inform subsequent decisions.",
    "parameters": [
      {
        "name": "planning_reasoning",
        "type": "reasoning",
        "description": "The reasoning node indicating that environment or resource state is unknown, must be checked, or is relevant to planning."
      },
      {
        "name": "exploratory_action",
        "type": "action",
        "description": "The action performing an inspection, listing, or query of the environment or resource state."
      },
      {
        "name": "state_observation",
        "type": "observation",
        "description": "The observation reporting the inspected environment or resource state."
      }
    ],
    "assertion_conditions": [
      "The reasoning indicates that some environment or resource state is unknown, must be checked, or is relevant to planning.",
      "The exploratory action inspects, lists, or queries that environment or resource state rather than performing a substantive transformation or final computation.",
      "The observation reports state information relevant to subsequent planning or decisions."
    ],
    "exclusion_conditions": [
      "The action performs a substantive transformation or final computation rather than an inspection of state.",
      "The reasoning already has the relevant state and expresses no reconnaissance need.",
      "The observation is unrelated to the environment or resource state being surveyed."
    ]
  },
  {
    "name": "EXPLORATORY_INSPECTION_REVEALS_CAPABILITY",
    "definition": "A non-mutating inspection of an available artifact or resource produces an observation that reveals an existing feature, option, component, or support already provided by it; the reasoning then explicitly recognizes that revealed capability as available and usable for the task.",
    "parameters": [
      {
        "name": "inspection_action",
        "type": "action",
        "description": "The action inspecting an available artifact or resource to learn its contents, options, or capabilities, without modifying it."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation reporting the existing feature, option, component, or support uncovered by the inspection."
      },
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that explicitly recognizes the revealed capability as available and usable for the task."
      }
    ],
    "assertion_conditions": [
      "The action inspects an available artifact or resource rather than modifying it or executing the target system.",
      "The observation reports an identifiable feature, option, component, or support that already exists in the inspected artifact or resource and is relevant to the task.",
      "The reasoning explicitly acknowledges that revealed capability as available and usable for accomplishing the task."
    ],
    "exclusion_conditions": [
      "The action modifies the artifact or executes the target system rather than inspecting it.",
      "The observation contains no identifiable existing feature, option, component, or support.",
      "The reasoning does not recognize or adopt the revealed capability as usable.",
      "What is reported is the absence or unavailability of a capability rather than an existing usable capability."
    ]
  }
]

Previously Generated Predicate Names:
["CONFIGURES_EVENT_DRIVEN_AUTOMATION", "PREVENTS_SELF_CAUSED_ADVERSE_EFFECTS_THROUGH_CORRECTIVE_ACTION", "EVALUATES_CANDIDATE_AGAINST_ENUMERATED_CONSTRAINTS_OR_SCENARIOS", "RESOLVES_EVALUATED_CANDIDATE_ELEMENTS_TO_SINGLE_RESULT", "INTERPRETS_REQUIREMENTS_FOR_ACTION_ADMISSIBILITY", "INITIATES_DETACHED_ASYNCHRONOUS_EXECUTION", "REPORTS_ABSENT_OR_UNAVAILABLE_CAPABILITY", "IDENTIFIES_SPECIFIC_POTENTIAL_FAILURE_MODE", "ASSESSES_COMPETING_ACCOUNTS_OF_SAME_OBSERVATION", "ESTABLISHES_EVIDENCE_GROUNDED_TASK_OUTCOME_REFERENCE", "FORMULATES_STRUCTURED_OPERATIVE_ACCOUNT", "SPECIFIES_TARGET_LINKED_CONCRETE_MEANS", "GROUNDS_COMPUTATIONAL_ASSESSMENT_IN_QUANTITATIVE_ANALYSIS", "ANTICIPATES_PROSPECTIVE_VERIFICATION", "DELIMITS_MODIFICATION_AND_RESIDUAL_ARTIFACT_SCOPE", "IDENTIFIES_DEFICIENCY_OR_INCOMPLETENESS", "REPRODUCES_SPECIFIED_PROCEDURE_OR_OPERATION_ORDER", "IMPLEMENTS_LIMITATION_RESPONSIVE_ALTERNATIVE_APPROACH", "EXECUTES_REASONED_REMOVAL_OF_UNWANTED_STATE", "RESOLVES_CANDIDATE_STATUS_FROM_OBSERVED_EVIDENCE", "GROUNDS_REASONING_SPECIFICATION_IN_OBSERVED_ACTION_OR_STATE", "MATERIALIZES_SPECIFIED_CONTENT_IN_DESIGNATED_ARTIFACT", "INTERPRETS_PROBLEMATIC_OBSERVATION_FOR_UNDERSTANDING_OR_RESPONSE", "GROUNDS_CONSTRAINT_OR_JUDGMENT_IN_OBSERVED_EVIDENCE", "CONFIRMS_INTENDED_EFFECT_OR_REQUIRED_STATE_FROM_OBSERVED_RESULT", "PRESERVES_VERIFIED_SUBSTANCE_DURING_REPRESENTATIONAL_REVISION", "CONSTRAINT_DRIVEN_ARTIFACT_ELIMINATION_OR_REVISION", "GENERALIZES_INFERRED_RULE_BEYOND_OBSERVED_EXAMPLES", "RECONSTRUCTS_ANCESTRY_OR_DIVERGENCE_FROM_VERSION_IDENTIFIERS", "INTEGRATES_MULTIPLE_OBSERVATIONS_INTO_UNIFIED_REPRESENTATION", "DIRECTS_INVESTIGATIVE_FOCUS_FROM_OBSERVED_FEATURE", "INTERPRETS_OBSERVED_CONTENT_AS_TYPED_OR_STRUCTURED_INFORMATION", "DERIVES_GOVERNING_ARTIFACT_JUDGMENT_FROM_OBSERVED_CONTENT", "DISCRIMINATES_BENIGN_REFERENCE_OCCURRENCES_FROM_ACTUAL_TARGETS", "RECORDS_DURABLE_ARTIFACT_STATE_REFERENCE_FOR_COMPARISON_OR_HISTORY", "PERSISTS_VALIDATED_STATE_TO_AUTHORITATIVE_STORE", "DERIVES_CONCRETE_TARGET_LOCATION_FROM_OBSERVED_LAYOUT_METADATA"]

Read every member's complete definition, ordered parameters, assertion conditions, and exclusion conditions. Identify the common underlying behavioral mechanism and generate exactly one complete predicate following the system instructions. The new predicate must preserve the cluster arity. Use a unique predicate name that does not conflict with previously generated predicate names. Return only the complete five-field JSON predicate.

message.content:
{
  "name": "RESOLVES_TASK_RELEVANT_PREREQUISITE_OR_ENVIRONMENT_STATE",
  "definition": "The reasoning identifies or recognizes a task-relevant dependency, unknown or unchecked environment or resource condition, missing or inadequate prerequisite, or existing capability whose status matters for planning or execution; a preparatory action—such as checking availability, version, or readiness, inspecting or querying state, provisioning a missing prerequisite, or non-mutating examination—is directed at that specific condition rather than at the task's primary transformation; and the observation reports the resulting status, successful preparation, revealed state, or confirmed usable capability so that it can inform subsequent action.",
  "parameters": [
    {
      "name": "task_need_reasoning",
      "type": "reasoning",
      "description": "The reasoning node that establishes or acknowledges a task-relevant condition: a dependency or unknown or unchecked state to be resolved, a missing or inadequate prerequisite to be supplied, or a capability revealed by inspection as available and usable for the task."
    },
    {
      "name": "preparatory_action",
      "type": "action",
      "description": "The action causally directed at the identified prerequisite, environment, resource, or capability condition, such as querying, inspecting, listing, checking, installing, fetching, refreshing, or otherwise preparing it rather than performing the task's primary substantive transformation."
    },
    {
      "name": "result_observation",
      "type": "observation",
      "description": "The observation reporting concrete status information about the identified condition, such as availability, version, readiness, environment or resource state, successful provisioning or preparation, or an existing usable feature or capability."
    }
  ],
  "assertion_conditions": [
    "The reasoning establishes or acknowledges a task-relevant condition: a dependency or unknown or unchecked state to be resolved, a missing or inadequate prerequisite, or a capability revealed by inspection as usable.",
    "The preparatory action is causally directed at that identified condition by querying, inspecting, listing, checking, installing, fetching, refreshing, or otherwise preparing it, and the action does not itself perform the task's primary substantive transformation or final computation.",
    "The observation reports concrete status information about the identified condition, including at least one of availability, version, readiness, environment or resource state, successful provisioning or preparation, or an existing usable feature or capability.",
    "The reported status is consistent with the identified condition and provides information usable for subsequent planning or execution; where the action provisions something, the observation confirms that the prerequisite became available or prepared."
  ],
  "exclusion_conditions": [
    "The reasoning does not identify or acknowledge any task-relevant prerequisite, environment or resource state, or capability condition to be checked, supplied, surveyed, or recognized.",
    "The action is unrelated to the identified condition or performs substantive primary task work rather than a check, inspection, survey, or provisioning step.",
    "The observation does not report the relevant state, availability, readiness, successful preparation, or revealed capability, or the action outcome remains unknown.",
    "The action provisions something merely convenient rather than a prerequisite identified as required for the task, or the action and observation are not linked to the condition identified or recognized by the reasoning."
  ]
}

